import json

path = "qc.ipynb"
nb = json.load(open(path))

md = "# GCH / HCG detected loci\n"

load = '''# Per-cell detected GCH / HCG loci, counted from BisSNP `*.6plus2.bed` files
# (loci = number of data rows; one row per detected cytosine in that context).
# Generated by summary/count_gch_hcg.py -> summary/gch_hcg_counts/.
#   GCH (GpC accessibility): NOMe methods only -> scnome, scnomehic
#   HCG (CpG methylation):   all methods (non-NOMe use the `CG` 6plus2 file)
# scnomehic uses the gm_sc_new (GM12878) calmd.cytosine.filtered.sort 6plus2 BEDs.
import os
import numpy as np
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
import matplotlib.ticker as ticker

gch_hcg = pd.read_csv("summary/gch_hcg_counts/all_methods.gch_hcg_loci.txt", sep="\\t")
for c in ["GCH_n", "HCG_n"]:
    gch_hcg[c] = pd.to_numeric(gch_hcg[c], errors="coerce")

print("cells per dataset:\\n", gch_hcg["dataset"].value_counts())
print("\\nmedian loci per dataset:")
print(gch_hcg.groupby("dataset")[["GCH_n", "HCG_n"]].median())
gch_hcg.head()
'''

plot = '''# --- publication style (matches the other QC violins) ---
sns.set_context("paper", font_scale=1.8)
sns.set_style("whitegrid")
plt.rcParams["pdf.fonttype"] = 42
plt.rcParams["ps.fonttype"] = 42

palette = {
    "nagano": "#CC79A7", "droplethic": "#0072B2", "scnome": "#D55E00",
    "smallwood": "#009E73", "snmCseq2": "#E69F00", "snmCseq3": "#56B4E9",
    "scnomehic": "#FF0000",
}

def winsorize_to_whiskers(df, value_col, group_col="dataset"):
    fixed = []
    for _, sub in df.groupby(group_col, sort=False):
        sub = sub.copy()
        q1 = sub[value_col].quantile(0.25)
        q3 = sub[value_col].quantile(0.75)
        iqr = q3 - q1
        sub[value_col] = sub[value_col].clip(q1 - 1.5 * iqr, q3 + 1.5 * iqr)
        fixed.append(sub)
    return pd.concat(fixed, axis=0, ignore_index=True)

def loci_violin(df, value_col, order, title, ylabel, fname):
    d = df.dropna(subset=[value_col]).copy()
    d = d[d[value_col] > 0]
    d = winsorize_to_whiskers(d, value_col)
    print("N per dataset:\\n", d["dataset"].value_counts().reindex(order))
    plt.figure(figsize=(6, 8))
    ax = sns.violinplot(
        data=d, x="dataset", y=value_col, order=order, palette=palette,
        inner="box", cut=0, bw_adjust=0.8, linewidth=1.4,
    )
    ax.set_xlabel("")
    ax.set_title(title, fontsize=20, pad=14)
    ax.set_ylabel(ylabel, fontsize=18, labelpad=10)
    ax.set_yscale("log")
    ax.yaxis.set_major_formatter(ticker.LogFormatterMathtext(base=10))
    ax.set_xticklabels(ax.get_xticklabels(), rotation=45, ha="right")
    plt.tight_layout()
    os.makedirs("figures", exist_ok=True)
    plt.savefig(fname, dpi=300)
    plt.savefig(fname.replace(".pdf", ".png"), dpi=300)
    plt.show()

# HCG (CpG) loci -- all methylation methods
loci_violin(
    gch_hcg, "HCG_n",
    order=["scnome", "smallwood", "snmCseq2", "snmCseq3", "scnomehic"],
    title="Detected HCG (CpG) Loci per Cell",
    ylabel="HCG loci (count)",
    fname="figures/hcg_loci_violin.pdf",
)

# GCH (GpC accessibility) loci -- NOMe methods only
loci_violin(
    gch_hcg, "GCH_n",
    order=["scnome", "scnomehic"],
    title="Detected GCH Loci per Cell",
    ylabel="GCH loci (count)",
    fname="figures/gch_loci_violin.pdf",
)
'''

# fill the three empty trailing cells (54 md, 55 load, 56 plot)
for idx, ctype, body in [(54, "markdown", md), (55, "code", load), (56, "code", plot)]:
    cell = nb["cells"][idx]
    assert "".join(cell["source"]).strip() == "", f"cell {idx} not empty"
    cell["cell_type"] = ctype
    cell["source"] = body.splitlines(keepends=True)
    if ctype == "code":
        cell["outputs"] = []
        cell["execution_count"] = None
        cell.pop("execution_count", None)
        cell["execution_count"] = None
    else:
        cell.pop("outputs", None)
        cell.pop("execution_count", None)

json.dump(nb, open(path, "w"), indent=1)
print("added GCH/HCG cells at 54-56; total cells:", len(nb["cells"]))
